import { useMemo } from "react";
import { columnColors, neonColors } from "../constants/color";
import { ColumnProps } from "../types";
import CardItem from "./Card";
import {
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { useDroppable } from "@dnd-kit/core";

export default function Column({ column, cards, index }: ColumnProps) {
  const color = columnColors[index];
  const { setNodeRef } = useDroppable({
  id: column.id,
});
  const randomColor = useMemo(() => {
    return neonColors[Math.floor(Math.random() * neonColors.length)];
  }, []);
  return (
    <div
    ref={setNodeRef}
      style={{
        flex: 1,
        height: "100%",
        padding: 10,
        borderWidth: 3,
        borderStyle: "solid",
        borderColor: color,
        borderRadius: 10,
        display: "flex",
        flexDirection: "column",
      }}
    >
      <h2 style={{ color: color }}>{column.title}</h2>
      <SortableContext
        items={column.cardIds}
        strategy={verticalListSortingStrategy}
      >
        {column.cardIds.map((id) => (
          <CardItem  id={id} key={id} card={cards[id]} color={randomColor}/>
        ))}
      </SortableContext>
    </div>
  );
}
